window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5dd9e0c49c550406"]={"versions": [{"id": "FIG-5dd9e0c49c550406", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) aus der AUTOSAR-Spezifikation des Log- and Trace-Extracts (<code>AUTOSAR_TPS_LogAndTraceExtract</code>). Es definiert die statische Struktur und Hierarchie zur Modellierung von Dlt-Steuergeräten (<code>DltEcu</code>), den zugeordneten Applikationen (<code>DltApplication</code>) und deren Kontexten (<code>DltContext</code>) für das Diagnostic Log and Trace (DLT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert drei zentrale Klassen:</p>\n<ul class=\"fig-list\"><li><strong><code>DltEcu</code></strong> (spezialisiert <code>ARElement</code>): Repräsentiert das Steuergerät.\n<ul class=\"fig-list\"><li>Attribut: <code>+ ecuId: String [0..1]</code> (optionale logische ECU-Kennung).\n</li></ul>\n</li><li><strong><code>DltApplication</code></strong> (spezialisiert <code>Identifiable</code>): Repräsentiert eine logische Software-Einheit bzw. Applikation auf dem Steuergerät.\n<ul class=\"fig-list\"><li>Attribute: <code>+ applicationDescription: String [0..1]</code>, <code>+ applicationId: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>DltContext</code></strong> (spezialisiert <code>ARElement</code>): Repräsentiert einen spezifischen Kontext innerhalb einer Applikation für gezieltes Logging/Tracing.\n<ul class=\"fig-list\"><li>Attribute: <code>+ contextDescription: String [0..1]</code>, <code>+ contextId: String [0..1]</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>DltEcu</code> zu <code>DltApplication</code>: Rolle <code>+application</code>, Multiplizität <code>0..*</code>, versehen mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li><li>Assoziation (gerichtete Navigation) von <code>DltApplication</code> zu <code>DltContext</code>: Rolle <code>+context</code>, Multiplizität <code>0..*</code>, versehen mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es spezifiziert die deklarative Konfigurations- und Extraktstruktur, die zur Entwurfs- bzw. Generierungszeit ausgewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-M2-Metamodell zur Extraktion von DLT-Metadaten.</p>\n<ul class=\"fig-list\"><li><code>DltEcu</code> und <code>DltContext</code> sind eigenständige <code>ARElement</code>-Paketelemente, während <code>DltApplication</code> ein untergeordnetes <code>Identifiable</code> darstellt.\n</li><li>Die Stereotypen <code>«atpVariation»</code> und <code>«atpSplitable»</code> an den Assoziationen <code>application</code> und <code>context</code> erlauben Variantenbildung (Post-Build/Pre-Compile Variation Points) sowie das Aufteilen der Elementdefinitionen über mehrere ARXML-Dateien/Fragmente hinweg.\n</li><li>Kennungen (<code>ecuId</code>, <code>applicationId</code>, <code>contextId</code>) sowie Beschreibungen sind optional modelliert (<code>[0..1]</code>), in der praktischen DLT-Nutzung für Protokoll-Header jedoch zumeist auf maximal 4-Zeichen-IDs ausgelegt.\n</li></ul>"}, {"id": "FIG-7eb47ce840ab53f2", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt) aus der AUTOSAR-Spezifikation des Log- and Trace-Extracts (<code>AUTOSAR_TPS_LogAndTraceExtract</code>). Es definiert die statische Struktur und Hierarchie zur Modellierung von Dlt-Steuergeräten (<code>DltEcu</code>), den zugeordneten Applikationen (<code>DltApplication</code>) und deren Kontexten (<code>DltContext</code>) für das Diagnostic Log and Trace (DLT).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert drei zentrale Klassen:</p>\n<ul class=\"fig-list\"><li><strong><code>DltEcu</code></strong> (spezialisiert <code>ARElement</code>): Repräsentiert das Steuergerät.\n<ul class=\"fig-list\"><li>Attribut: <code>+ ecuId: String [0..1]</code> (optionale logische ECU-Kennung).\n</li></ul>\n</li><li><strong><code>DltApplication</code></strong> (spezialisiert <code>Identifiable</code>): Repräsentiert eine logische Software-Einheit bzw. Applikation auf dem Steuergerät.\n<ul class=\"fig-list\"><li>Attribute: <code>+ applicationDescription: String [0..1]</code>, <code>+ applicationId: String [0..1]</code>.\n</li></ul>\n</li><li><strong><code>DltContext</code></strong> (spezialisiert <code>ARElement</code>): Repräsentiert einen spezifischen Kontext innerhalb einer Applikation für gezieltes Logging/Tracing.\n<ul class=\"fig-list\"><li>Attribute: <code>+ contextDescription: String [0..1]</code>, <code>+ contextId: String [0..1]</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>DltEcu</code> zu <code>DltApplication</code>: Rolle <code>+application</code>, Multiplizität <code>0..*</code>, versehen mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li><li>Assoziation (gerichtete Navigation) von <code>DltApplication</code> zu <code>DltContext</code>: Rolle <code>+context</code>, Multiplizität <code>0..*</code>, versehen mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es spezifiziert die deklarative Konfigurations- und Extraktstruktur, die zur Entwurfs- bzw. Generierungszeit ausgewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives AUTOSAR-M2-Metamodell zur Extraktion von DLT-Metadaten.</p>\n<ul class=\"fig-list\"><li><code>DltEcu</code> und <code>DltContext</code> sind eigenständige <code>ARElement</code>-Paketelemente, während <code>DltApplication</code> ein untergeordnetes <code>Identifiable</code> darstellt.\n</li><li>Die Stereotypen <code>«atpVariation»</code> und <code>«atpSplitable»</code> an den Assoziationen <code>application</code> und <code>context</code> erlauben Variantenbildung (Post-Build/Pre-Compile Variation Points) sowie das Aufteilen der Elementdefinitionen über mehrere ARXML-Dateien/Fragmente hinweg.\n</li><li>Kennungen (<code>ecuId</code>, <code>applicationId</code>, <code>contextId</code>) sowie Beschreibungen sind optional modelliert (<code>[0..1]</code>), in der praktischen DLT-Nutzung für Protokoll-Header jedoch zumeist auf maximal 4-Zeichen-IDs ausgelegt.\n</li></ul>"}], "trans": [{"from": "FIG-5dd9e0c49c550406", "to": "FIG-7eb47ce840ab53f2", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
